// --- System Call & ECF Flow: File Open ---

// User Mode starts execution
int fd;

// The library wrapper executes a specific trap instruction
// ECF occurs: User Mode -> Kernel Mode (Privilege escalation)
fd = open("/etc/passwd", O_RDONLY);

// Kernel checks permissions (User ID vs File permissions)
// Kernel performs I/O operation

if (fd < 0) {
    // Kernel sets return register to -1, updates error code
    // ECF returns: Kernel Mode -> User Mode (Privilege de-escalation)
    perror("open error");
} else {
    // Read operation (another system call/ECF cycle)
    char buffer[100];
    read(fd, buffer, 100);
    close(fd); // Final cleanup syscall
}
